INSERT INTO candidates VALUES(1010099593,'R_kgDOPDTliQ','2733683116/JavaWeb_Zero_Foundation_SelfStudy','https://github.com/2733683116/JavaWeb_Zero_Foundation_SelfStudy','{"id":1010099593,"node_id":"R_kgDOPDTliQ","name":"JavaWeb_Zero_Foundation_SelfStudy","full_name":"2733683116/JavaWeb_Zero_Foundation_SelfStudy","private":false,"owner":{"login":"2733683116","id":92662454,"node_id":"U_kgDOBYXqtg","avatar_url":"https://avatars.githubusercontent.com/u/92662454?v=4","gravatar_id":"","url":"https://api.github.com/users/2733683116","html_url":"https://github.com/2733683116","followers_url":"https://api.github.com/users/2733683116/followers","following_url":"https://api.github.com/users/2733683116/following{/other_user}","gists_url":"https://api.github.com/users/2733683116/gists{/gist_id}","starred_url":"https://api.github.com/users/2733683116/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/2733683116/subscriptions","organizations_url":"https://api.github.com/users/2733683116/orgs","repos_url":"https://api.github.com/users/2733683116/repos","events_url":"https://api.github.com/users/2733683116/events{/privacy}","received_events_url":"https://api.github.com/users/2733683116/received_events","type":"User","user_view_type":"public","site_admin":false},"html_url":"https://github.com/2733683116/JavaWeb_Zero_Foundation_SelfStudy","description":"在数字化浪潮席卷全球的当下，JavaWeb 技术凭借其强大的跨平台性、稳定的性能和庞大的生态系统，成为众多开发者构建企业级应用、互联网项目的首选技术栈。无论是想要进入软件开发行业的职场新人，还是期望拓展技能边界的技术爱好者，系统学习 JavaWeb 都能为职业发展和个人成长带来新的机遇。因此，精心规划一条 JavaWeb 零基础自学路线，不仅是为了帮助那些同样怀揣技术梦想的学习者少走弯路，更是对自身知识体系的一次深度梳理与巩固 —— 通过从基础语法到框架实战的系统化学习，既能搭建完整的技术认知框架，又能在总结输出的过程中强化知识内化，最终实现个人技术能力与教学赋能的双向提升。","fork":false,"url":"https://api.github.com/repos/2733683116/JavaWeb_Zero_Foundation_SelfStudy","forks_url":"https://api.github.com/repos/2733683116/JavaWeb_Zero_Foundation_SelfStudy/forks","keys_url":"https://api.github.com/repos/2733683116/JavaWeb_Zero_Foundation_SelfStudy/keys{/key_id}","collaborators_url":"https://api.gith